fn denoise_serve_runs_tiles_for_another_computer() {
    use lightcraft_denoise::manifest::{DenoiserManifest, Domain, Gain};
    use lightcraft_denoise::remote::Remote;
    use lightcraft_denoise::run::TileRunner;
    { ... }
        id: "synthetic".into(),
